<?php
declare(strict_types=1);
require __DIR__ . '/includes/bootstrap.php';
$user=app_require_permission('wholesale.view');$canManage=app_has_permission('wholesale.manage',$user);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Wholesale Customer Accounts</title><style>:root{--bg:#f2f1ed;--panel:#fff;--ink:#171815;--muted:#6b706a;--line:#deded8;--accent:#d94a2b;--dark:#171b1a;--good:#157347}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif}button,input,select,textarea{font:inherit}.top{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 22px;background:#fff;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:20}.brand{display:flex;align-items:center;gap:10px}.logo{width:38px;height:38px;display:grid;place-items:center;border-radius:11px;background:var(--dark);color:#fff;font-weight:900}.brand small{display:block;color:var(--muted);font-size:9px}.actions{display:flex;gap:7px}.btn{min-height:38px;padding:8px 11px;border:1px solid var(--line);border-radius:9px;background:#fff;color:var(--ink);font-weight:850;font-size:10px;text-decoration:none;cursor:pointer}.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}.shell{padding:26px;max-width:1500px;margin:auto}.head{display:flex;justify-content:space-between;gap:20px;align-items:flex-end;margin-bottom:16px}.eyebrow{margin:0;color:var(--accent);font-size:9px;font-weight:950;text-transform:uppercase;letter-spacing:.12em}.head h1{margin:6px 0 0;font-size:38px;letter-spacing:-.05em}.head p:last-child{max-width:760px;color:var(--muted);font-size:12px}.create{display:grid;grid-template-columns:1fr auto;gap:8px;margin-bottom:16px;padding:14px;border:1px solid var(--line);border-radius:15px;background:#fff}.field{width:100%;min-height:40px;border:1px solid var(--line);border-radius:9px;padding:9px 10px;background:#fff}.accounts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.card{padding:16px;border:1px solid var(--line);border-radius:16px;background:#fff;cursor:pointer}.card:hover{border-color:#d9a08e}.card h3{margin:0 0 5px;font-size:15px}.muted{color:var(--muted);font-size:10px;line-height:1.45}.chips{display:flex;gap:5px;flex-wrap:wrap;margin-top:10px}.chip{padding:5px 7px;border-radius:999px;background:#f0efeb;color:#5e635e;font-size:8px;font-weight:900}.drawer{position:fixed;top:0;right:-680px;width:min(660px,96vw);height:100vh;z-index:50;background:#fff;border-left:1px solid var(--line);box-shadow:-20px 0 50px rgba(0,0,0,.14);transition:.2s;overflow:auto}.drawer.open{right:0}.drawer-head{position:sticky;top:0;z-index:3;display:flex;justify-content:space-between;align-items:flex-start;padding:20px;border-bottom:1px solid var(--line);background:#fff}.drawer-head h2{margin:5px 0 0}.close{width:38px;height:38px;border:0;border-radius:10px;background:#f1f0ec;font-size:20px}.body{padding:20px}.section{margin-top:18px;padding-top:16px;border-top:1px solid var(--line)}.section h3{margin:0 0 9px;font-size:13px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.grid .wide{grid-column:1/-1}label{display:block;margin-bottom:4px;color:#595e59;font-size:8px;font-weight:900}.list{display:grid;gap:7px}.row{padding:10px;border:1px solid var(--line);border-radius:10px}.rowtop{display:flex;justify-content:space-between;gap:8px}.row strong{font-size:10px}.row small{color:var(--muted);font-size:8px}.invite-result{margin-top:8px;padding:9px;border-radius:9px;background:#eef8f1;color:#145c38;font-size:9px;word-break:break-all}.empty{padding:25px;text-align:center;border:1px dashed #cacac5;border-radius:12px;color:var(--muted);font-size:10px}@media(max-width:950px){.accounts{grid-template-columns:1fr 1fr}}@media(max-width:650px){.accounts,.grid{grid-template-columns:1fr}.grid .wide{grid-column:auto}.create{grid-template-columns:1fr}.head{align-items:flex-start;flex-direction:column}}</style></head><body><header class="top"><div class="brand"><div class="logo">G</div><div><strong>Wholesale Customers</strong><small>Buyer accounts · portal access · quotes · orders</small></div></div><div class="actions"><a class="btn" href="wholesale-pipeline.php">Pipeline</a><a class="btn" href="index.php">Workspace</a></div></header><main class="shell"><div class="head"><div><p class="eyebrow">Customer relationship layer</p><h1>Wholesale customer accounts</h1><p>Convert qualified pipeline leads into private customer workspaces, invite buyer logins, issue quotes and orders, and review customer requests.</p></div><button class="btn" id="refresh">Refresh</button></div><?php if($canManage):?><div class="create"><select class="field" id="leadSelect"><option value="">Choose an unconverted wholesale lead…</option></select><button class="btn primary" id="createAccount">Create customer account</button></div><?php endif;?><div class="accounts" id="accounts"></div></main><aside class="drawer" id="drawer"><div class="drawer-head"><div><p class="eyebrow">Wholesale customer</p><h2 id="drawerTitle">Account</h2></div><button class="close" id="drawerClose">×</button></div><div class="body" id="drawerBody"></div></aside><script>window.WA={csrf:<?=json_encode(app_csrf_token(),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,canManage:<?=$canManage?'true':'false'?>};</script><script>
(()=>{const cfg=window.WA,$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])),money=v=>'$'+Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});let accounts=[],active='';async function api(url,opt={}){const r=await fetch(url,{cache:'no-store',headers:{Accept:'application/json',...(opt.body?{'Content-Type':'application/json','X-CSRF-Token':cfg.csrf}:{}),...(opt.headers||{})},...opt});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Request failed');return d}async function load(){const d=await api('api/wholesale-accounts.php?action=list');accounts=d.accounts||[];$('accounts').innerHTML=accounts.length?accounts.map(a=>`<article class="card" data-id="${esc(a.public_id)}"><h3>${esc(a.business_name)}</h3><div class="muted">${esc(a.primary_email||'No email')} · ${esc(a.business_type||'Wholesale customer')}</div><div class="chips"><span class="chip">${esc(a.account_status)}</span><span class="chip">${Number(a.user_count||0)} portal user${Number(a.user_count||0)===1?'':'s'}</span><span class="chip">${Number(a.open_request_count||0)} open request${Number(a.open_request_count||0)===1?'':'s'}</span>${a.pipeline_stage?`<span class="chip">Pipeline: ${esc(a.pipeline_stage)}</span>`:''}</div></article>`).join(''):'<div class="empty">No wholesale customer accounts yet.</div>';document.querySelectorAll('.card[data-id]').forEach(c=>c.onclick=()=>open(c.dataset.id));if($('leadSelect'))$('leadSelect').innerHTML='<option value="">Choose an unconverted wholesale lead…</option>'+((d.availableLeads||[]).map(l=>`<option value="${esc(l.public_id)}">${esc(l.business_name)} · ${esc(l.pipeline_stage)} · ${esc(l.contact_name)}</option>`).join(''));if(active)open(active)}function itemsText(v){try{return (JSON.parse(v||'[]')||[]).map(x=>typeof x==='string'?x:[x.quantity,x.unit,x.name||x.item||x.product,x.flavor].filter(Boolean).join(' ')).join(' · ')}catch{return ''}}async function open(id){active=id;const d=await api('api/wholesale-accounts.php?action=detail&id='+encodeURIComponent(id)),a=d.account;$('drawerTitle').textContent=a.business_name;$('drawer').classList.add('open');$('drawerBody').innerHTML=`<div class="grid"><div><label>Status</label><div class="row"><strong>${esc(a.account_status)}</strong></div></div><div><label>Primary email</label><div class="row"><strong>${esc(a.primary_email||'—')}</strong></div></div><div><label>Price tier</label><div class="row"><strong>${esc(a.price_tier||'—')}</strong></div></div><div><label>Terms</label><div class="row"><strong>${esc(a.payment_terms||'—')}</strong></div></div></div>${cfg.canManage?inviteForm(a):''}<div class="section"><h3>Portal users</h3><div class="list">${(d.users||[]).length?(d.users||[]).map(u=>`<div class="row"><div class="rowtop"><strong>${esc(u.display_name)} · ${esc(u.account_role)}</strong><small>${esc(u.last_login_at||'Never signed in')}</small></div><div class="muted">${esc(u.email)}</div></div>`).join(''):'<div class="empty">No buyer login accepted yet.</div>'}</div></div>${cfg.canManage?quoteForm():''}<div class="section"><h3>Quotes</h3><div class="list">${(d.quotes||[]).length?(d.quotes||[]).map(q=>`<div class="row"><div class="rowtop"><strong>${esc(q.quote_number)} · ${money(q.total)}</strong><span class="chip">${esc(q.status)}</span></div><div class="muted">${esc(itemsText(q.items_json))}</div></div>`).join(''):'<div class="empty">No quotes yet.</div>'}</div></div>${cfg.canManage?orderForm():''}<div class="section"><h3>Orders</h3><div class="list">${(d.orders||[]).length?(d.orders||[]).map(o=>`<div class="row"><div class="rowtop"><strong>${esc(o.order_number)} · ${money(o.total)}</strong><span class="chip">${esc(o.status)}</span></div><div class="muted">${esc(itemsText(o.items_json))}</div></div>`).join(''):'<div class="empty">No orders yet.</div>'}</div></div><div class="section"><h3>Customer requests</h3><div class="list">${(d.requests||[]).length?(d.requests||[]).map(r=>`<div class="row"><div class="rowtop"><strong>${esc(r.subject)}</strong><span class="chip">${esc(r.status)}</span></div><div class="muted">${esc(r.request_type)} · ${esc(r.submitted_by_name)}<br>${esc(r.details)}</div>${cfg.canManage&&r.status!=='closed'?`<button class="btn" data-close-request="${esc(r.public_id)}" style="margin-top:7px">Close request</button>`:''}</div>`).join(''):'<div class="empty">No requests yet.</div>'}</div></div>`;bindDrawer(id)}function inviteForm(a){return `<div class="section"><h3>Invite buyer login</h3><div class="grid"><div><label>Contact name</label><input class="field" id="iName"></div><div><label>Email</label><input class="field" id="iEmail" value="${esc(a.primary_email||'')}" type="email"></div><div><label>Portal role</label><select class="field" id="iRole"><option value="owner">Account owner</option><option value="buyer" selected>Buyer</option><option value="accounting">Accounting</option></select></div><div style="display:flex;align-items:end"><button class="btn primary" id="sendInvite" style="width:100%">Create invite</button></div></div><div id="inviteResult"></div></div>`}function quoteForm(){return `<div class="section"><h3>Create quote</h3><div class="grid"><div class="wide"><label>Items (one per line: quantity | product/flavor | unit price)</label><textarea class="field" id="qItems" rows="4" placeholder="2 | Pistachio 5L pan | 48.00"></textarea></div><div><label>Subtotal</label><input class="field" id="qSubtotal" type="number" step=".01"></div><div><label>Delivery fee</label><input class="field" id="qDelivery" type="number" step=".01" value="0"></div><div><label>Tax</label><input class="field" id="qTax" type="number" step=".01" value="0"></div><div><label>Valid until</label><input class="field" id="qValid" type="date"></div><div class="wide"><label>Customer message</label><textarea class="field" id="qMessage" rows="2"></textarea></div><div class="wide"><button class="btn primary" id="createQuote">Create & send quote</button></div></div></div>`}function orderForm(){return `<div class="section"><h3>Create order</h3><div class="grid"><div class="wide"><label>Items (one per line: quantity | product/flavor | unit price)</label><textarea class="field" id="oItems" rows="4"></textarea></div><div><label>Subtotal</label><input class="field" id="oSubtotal" type="number" step=".01"></div><div><label>Delivery fee</label><input class="field" id="oDelivery" type="number" step=".01" value="0"></div><div><label>Tax</label><input class="field" id="oTax" type="number" step=".01" value="0"></div><div><label>Status</label><select class="field" id="oStatus"><option>confirmed</option><option>requested</option><option>in_production</option><option>ready</option><option>out_for_delivery</option><option>delivered</option></select></div><div><label>Fulfillment</label><select class="field" id="oFulfillment"><option>Delivery</option><option>Pickup</option></select></div><div><label>Requested for</label><input class="field" id="oRequested" type="date"></div><div class="wide"><button class="btn primary" id="createOrder">Create order</button></div></div></div>`}function parseItems(text){return text.split(/\n+/).map(line=>line.trim()).filter(Boolean).map(line=>{const p=line.split('|').map(x=>x.trim());return {quantity:p[0]||'',product:p[1]||line,unitPrice:Number(p[2]||0)}})}function bindDrawer(accountId){if($('sendInvite'))$('sendInvite').onclick=async()=>{try{const d=await api('api/wholesale-accounts.php',{method:'POST',body:JSON.stringify({action:'invite',accountId,contactName:$('iName').value,email:$('iEmail').value,accountRole:$('iRole').value,csrf_token:cfg.csrf})});$('inviteResult').innerHTML=`<div class="invite-result">${esc(d.message)}<br><strong>${esc(d.inviteUrl)}</strong></div>`;await load()}catch(e){alert(e.message)}};if($('createQuote'))$('createQuote').onclick=async()=>{try{const subtotal=Number($('qSubtotal').value||0),delivery=Number($('qDelivery').value||0),tax=Number($('qTax').value||0);const d=await api('api/wholesale-accounts.php',{method:'POST',body:JSON.stringify({action:'quote',accountId,items:parseItems($('qItems').value),subtotal,deliveryFee:delivery,taxTotal:tax,total:subtotal+delivery+tax,validUntil:$('qValid').value,customerMessage:$('qMessage').value,status:'sent',csrf_token:cfg.csrf})});alert(d.message+' '+d.quoteNumber);await open(accountId)}catch(e){alert(e.message)}};if($('createOrder'))$('createOrder').onclick=async()=>{try{const subtotal=Number($('oSubtotal').value||0),delivery=Number($('oDelivery').value||0),tax=Number($('oTax').value||0);const d=await api('api/wholesale-accounts.php',{method:'POST',body:JSON.stringify({action:'order',accountId,items:parseItems($('oItems').value),subtotal,deliveryFee:delivery,taxTotal:tax,total:subtotal+delivery+tax,status:$('oStatus').value,fulfillmentType:$('oFulfillment').value,requestedFor:$('oRequested').value,csrf_token:cfg.csrf})});alert(d.message+' '+d.orderNumber);await open(accountId)}catch(e){alert(e.message)}};document.querySelectorAll('[data-close-request]').forEach(b=>b.onclick=async()=>{try{await api('api/wholesale-accounts.php',{method:'POST',body:JSON.stringify({action:'request_status',accountId,requestId:b.dataset.closeRequest,status:'closed',csrf_token:cfg.csrf})});await open(accountId)}catch(e){alert(e.message)}})}if($('createAccount'))$('createAccount').onclick=async()=>{const leadId=$('leadSelect').value;if(!leadId)return;try{const d=await api('api/wholesale-accounts.php',{method:'POST',body:JSON.stringify({action:'create_account',leadId,csrf_token:cfg.csrf})});await load();open(d.accountId)}catch(e){alert(e.message)}};$('refresh').onclick=load;$('drawerClose').onclick=()=>{$('drawer').classList.remove('open');active=''};load().catch(e=>alert(e.message));})();
</script></body></html>